/**
 * Docs parameters for a catalog component: its plain-language purpose plus the status, styles, tokens and
 * accessibility notes read from components.json, so they are never duplicated. `folder` is the React component's
 * folder once it lives in `src/`; without it the story is still a v1.0 markup spec.
 */
export function componentDocs(name: string, purpose: string, folder?: string) {
  const c = catalog.components.find((x) => x.name === name);
  if (!c) throw new Error(`"${name}" is not in components.json`);
  const status =
    c.status === 'core'
      ? '**Núcleo**: aceptado con la Ronda 05 (guía v1.0).'
      : '**Candidato**: se puede usar, pero la primera página que lo necesite lo confirma o lo descarta.';
  const text = [
    `**${c.label_es}** (\`${c.name}\` en \`components.json\`).`,
    purpose,
    status,
    'styles' in c
      ? `**Estilos:** \`${c.styles}\` (CSS Module propio)`
      : `**Clases:** ${c.classes.map((x) => `\`${x}\``).join(', ')}`,
    `**Tokens:** ${c.tokens.map((x) => `\`${x}\``).join(', ')}`,
    `**Accesibilidad:** ${A11Y_NOTES[name] ?? 'ver Accesibilidad.'}`,
    folder
      ? `_Componente React de la app: \`${folder}\`. Trae sus propios estilos y solo usa tokens \`--el-*\`._`
      : '_Especificación v1.0: marcado y clases `el-*`. Todavía no es un componente React de la app; cuando se implemente con el flujo `elephant-designer`, su historia vivirá junto al componente en `src/`._',
  ].join('\n\n');
  return { docs: { description: { component: text } } };
}

export function FictionalNote({ children = 'Datos ficticios.' }: { children?: string }) {
  return <p className="sb-el-fictional">{children}</p>;
}
